const output=text=>{const input=JSON.parse(text);assert.equal(readdirSync(process.cwd()).length,0);assert.equal(input.maxProposals,4);assert.equal(input.sources.length,2);assert.ok(!process.env.OPENAI_API_KEY);assert.ok(!process.env.ANTHROPIC_API_KEY);return JSON.stringify({proposals:[{content:'Prefere respostas objetivas e breves.',kind:'preference',confidence:'explicit',evidence:[input.sources.find(s=>s.role==='user').evidence]}]});};
